import java.util.*; public class GardenPlotAreaReport { public static void main(String[]a){Scanner s=new Scanner(System.in);int n=s.nextInt();double t=0;while(n-->0){String x=s.next(),o=s.next();double p=s.nextDouble(),q=x.equals("CIRCLE")?0:s.nextDouble(),r=x.equals("CIRCLE")?Math.PI*p*p:x.equals("RECTANGLE")?p*q:p*q/2;t+=r;System.out.printf("%s (%s): %.2f%n",o,x,r);}System.out.printf("Total Area: %.2f%n",t);} }
